# Mutações da 243a leva (itens cpf_1, cpf_2, cpf_3, cpg_1, cpg_2, cpg_3, cph_1). Uso: python mutacoes.py mutacoes\leva243.py --carreira 2002-06-01
MUTACOES = [
    ('cpf_nota_byte', '*((this + 0x1c) as *mut u8) = *((source + 0x1c) as *const u8); // the rating record byte', '*((this + 0x1c) as *mut u8) = 0; // mutacao: o byte zerado'),
    ('cpf_melhor_vezes', '*(this as *mut u8) = *(source as *const u8); // the man-of-the-match count', '*(this as *mut u8) = (*(source as *const u8)).wrapping_add(1); // mutacao: uma vez a mais'),
    ('cpf_disciplina_vermelhos', '*((this + 1) as *mut u8) = *((source + 1) as *const u8); // the reds', '*((this + 1) as *mut u8) = *(source as *const u8); // mutacao: os amarelos no lugar'),
    ('cpf_contagem', 'core::ptr::write_unaligned(this as *mut u16, core::ptr::read_unaligned(source as *const u16)); // a contagem', 'core::ptr::write_unaligned(this as *mut u16, core::ptr::read_unaligned(source as *const u16).wrapping_add(1)); // mutacao: uma a mais'),
    ('cpf_torcedor_ano', 'core::ptr::write_unaligned((this + 0x18) as *mut u16, core::ptr::read_unaligned((source + 0x18) as *const u16)); // the supporter’s year', 'core::ptr::write_unaligned((this + 0x18) as *mut u16, 0); // mutacao: o ano zerado'),
    ('cpf_ocorrencias_data', 'init_default_date(this + 0x11); // the date of the occurrences', 'init_default_date(this + 0x10); // mutacao: a data um byte antes'),
    ('cpf_contagem_data', 'init_default_date(this + 0x12); // the counting date', 'init_default_date(this + 0x11); // mutacao: a data um byte antes'),
    ('cpf_valor_troca', '*((this + 0x28) as *mut u8) = *((source + 0x28) as *const u8); // the swap flag', '*((this + 0x28) as *mut u8) = 1; // mutacao: sempre troca'),
    ('cpf_gols', '*(this as *mut u8) = *(source as *const u8); // the goals', '*(this as *mut u8) = (*(source as *const u8)).wrapping_add(1); // mutacao: um gol a mais'),
    ('cpg_noticia_fichas', 'for k in 0..50 {\n        d(5 + 4 * k); // the news item’s records', 'for k in 0..49 {\n        d(5 + 4 * k); // mutacao: sem a ultima ficha'),
    ('cpg_passada_duplas', 'for k in 0..7 {\n        core::ptr::write_unaligned((this + 4 * k) as *mut u32, core::ptr::read_unaligned((source + 4 * k) as *const u32)); // the transfer pairs', 'for k in 0..6 {\n        core::ptr::write_unaligned((this + 4 * k) as *mut u32, core::ptr::read_unaligned((source + 4 * k) as *const u32)); // mutacao: sem a ultima'),
    ('cpg_futura_oferta', 'core::ptr::write_unaligned((this + 8) as *mut u32, core::ptr::read_unaligned((source + 8) as *const u32)); // the offer index', 'core::ptr::write_unaligned((this + 8) as *mut u32, 0); // mutacao: a primeira oferta'),
    ('cpg_fila_pessoa', 'core::ptr::write_unaligned(this as *mut u32, core::ptr::read_unaligned(source as *const u32)); // the regen’s person', 'core::ptr::write_unaligned(this as *mut u32, core::ptr::read_unaligned(source as *const u32).wrapping_add(1)); // mutacao: a pessoa seguinte'),
    ('cpg_observados', '(p as u32 & !0xff) | (p != 0) as u32', '(p as u32 & !0xff) | 0 // mutacao: nunca esta'),
    ('cpg_doador_zero', 'if s > melhor && s > 0 { // the nation’s best', 'if s > melhor && s >= 0 { // mutacao: aceita nota zero'),
    ('cpg_suspensao_bits', '*m = (*m & !7) | (*((source + 0x13) as *const u8) & 7); // the three marks', '*m = (*m & !7) | (*((source + 0x13) as *const u8) & 3); // mutacao: so duas marcas'),
    ('cpg_salario_minimo', '*((this + staff_contract::WAGE) as *mut i32) = if v < 0x37 { 0x37 } else { v }; // the minimum of 55', '*((this + staff_contract::WAGE) as *mut i32) = if v < 0x38 { 0x38 } else { v }; // mutacao: minimo 56'),
    ('cpg_condicao_porcento', 'return match_pl_ftol(c as f64 * *(0x96bac8 as *const f32) as f64) as u16; // in percent', 'return (ftol(c as f64 * *(0x96bac8 as *const f32) as f64) - 1) as u16; // mutacao: um ponto a menos'),
    ('cph_dias_fim', 'days(this + staff_contract::CONTRACT_EXPIRES, read_u32(G_CURRENT_DATE), read_u32(G_CURRENT_DATE_LEAP)) // the contract end date', 'days(this + staff_contract::DATE_STARTED, read_u32(0xae2c90), read_u32(0xae2c94)) // mutacao: a data de inicio'),
    ('cph_queixas_zero', 'core::ptr::write_unaligned((this + staff_contract::GRIEVANCES) as *mut u32, 0); // the complaints', '*((this + staff_contract::GRIEVANCES) as *mut u8) = 0; // mutacao: so o byte baixo'),
    ('cph_retirada_moral', '*((this + staff_contract::MORALE) as *mut u8) = read_u8(pessoa + staff::PROFESSIONALISM).wrapping_add(read_u8(pessoa + staff::LOYALITY)).wrapping_add(5);', '*((this + staff_contract::MORALE) as *mut u8) = read_u8(pessoa + staff::PROFESSIONALISM).wrapping_add(read_u8(pessoa + staff::LOYALITY)).wrapping_add(4); // mutacao'),
    ('cph_retirada_felicidade', '*((this + 0x3d) as *mut u8) = 15; // the minimum happiness', '*((this + 0x3d) as *mut u8) = 14; // mutacao: 14'),
]
